import { writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import postcss from 'postcss';
import tailwindcss from 'tailwindcss';
import { axPreset } from '../src/tailwind/preset.js';

const src = fileURLToPath(new URL('../src', import.meta.url));
const HEADER =
  '/* Generated by scripts/build-css.ts from src/**/*.{ts,tsx} and the Tailwind preset. Do not edit; run pnpm --filter @project-ax/ui gen. */\n';

export async function renderUiCss(): Promise<string> {
  const result = await postcss([
    tailwindcss({
      presets: [axPreset],
      // Component sources only: tests mention classes on purpose and must not leak into ui.css.
      content: [`${src}/**/*.{ts,tsx}`, `!${src}/**/__tests__/**`],
    }),
  ]).process('@tailwind utilities;', { from: undefined });
  return HEADER + result.css + '\n';
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  writeFileSync(fileURLToPath(new URL('../ui.css', import.meta.url)), await renderUiCss());
}
